(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["vi"] = {"ui":{"skip":"Bỏ qua, đến nội dung","back":"← Quay lại AI-gile","lang.button":"Ngôn ngữ: {name}","lang.dialog":"Chọn một ngôn ngữ","lang.search":"Tìm ngôn ngữ","lang.none":"Không có ngôn ngữ nào khớp","lang.notYet":"{name} chưa được dịch","theme.aria":"Đổi giao diện: sáng, tối hoặc đen","theme.toLight":"Chuyển sang giao diện sáng","theme.toDark":"Chuyển sang giao diện tối","theme.toBlack":"Chuyển sang giao diện đen (đen tuyền, dịu mắt trên màn hình OLED)","words.underline":"Gạch chân những từ này trên trang","words.underlineHelp":"Di chuột hoặc chạm vào một từ có gạch chấm để xem nghĩa của nó.","index.title":"AI-gile: nhóm lập trình AI của bạn, trên một bảng","index.description":"AI-gile là bảng kanban cho các nhóm lập trình bằng AI. Họ làm việc khi bạn ngủ; bạn chỉ nhận một chồng ngắn những việc cần quyết định, thử và chấp nhận.","hero.logoAlt":"Biểu tượng bảng AI-gile","hero.h1.html":"Nhóm lập trình AI của bạn, trên một&nbsp;bảng.","hero.alpha":"🐣 Tiền alpha kín","hero.alphaTitle":"Còn sớm và chưa xong: cảm ơn bạn đã thử!","hero.lede":"Họ làm trong lúc bạn ngủ. Sáng ra bạn nhận một chồng ngắn: vài câu hỏi, vài thứ cần thử, một hai viên kim cương tím. Bấm, chấp nhận, rồi quay lại với ly cà phê.","dl.windows":"Ứng dụng Windows","dl.browser":"Chạy trong trình duyệt","dl.messenger":"📱 Messenger cho điện thoại","dl.soon":"Sắp ra mắt","dl.notify":"🔔 Báo cho tôi khi mở","dl.notifySmall":"Alpha hoặc beta","hero.secondary":"Agile, nhưng nhóm không bao giờ cần cà phê họp đứng. (Họ vẫn họp đứng thôi.)","pitch.h2":"AI-gile trong bao nhiêu từ tùy bạn","pitch.lede":"Chọn một độ dài, từ một từ đến 144. Mỗi độ dài là một bản mô tả riêng, viết cho đúng cỡ đó. Kéo thanh trượt hoặc dùng phím mũi tên.","pitch.rangeLabel":"Độ dài tính bằng từ","pitch.dice":"🎲 một bản khác","pitch.words.one":"{n} từ","pitch.words.other":"{n} từ","pitch.letters.one":"{n} chữ cái","pitch.letters.other":"{n} chữ cái","pitch.chars.one":"{n} ký tự","pitch.chars.other":"{n} ký tự","count.line.html.one":"{n} thẻ trên bảng ngay lúc này","count.line.html.other":"{n} thẻ trên bảng ngay lúc này","features.aria":"Nó làm gì","f.pile.h":"Một chồng dành cho bạn","f.pile.html":"<b>Cho bạn</b> gom mọi thứ đang chờ bạn ở tất cả dự án: câu hỏi, thứ cần thử, việc chỉ con người làm được. Hàng đợi cho biết việc tiếp theo là gì và mất bao lâu.","f.sleep.h":"Những nhóm làm việc khi bạn ngủ","f.sleep.p":"Mỗi dự án có một trưởng nhóm và một nhóm agent AI. Viết bình luận vào thẻ, nhóm sẽ thức dậy, làm việc, rồi giao lại kèm các bước mà một người mệt mỏi cũng làm theo được.","f.tester.h":"Một người kiểm thử AI xem trước","f.tester.p":"Trước khi gì đó đến tay bạn, người kiểm thử làm theo các bước trong một bản sao của ứng dụng và cho xem điều đã thấy, kèm ảnh chụp màn hình. Lướt qua những thẻ đã đạt và chấp nhận bằng một cú bấm.","f.proof.h":"Bằng chứng, không phải lời hứa","f.proof.p":"Mỗi lần bàn giao đều cho thấy điều gì đã đổi: các tệp, phần khác biệt, ảnh chụp màn hình. Không cần mở từng ứng dụng để xem đã xong chưa.","f.chat.h":"Trò chuyện với các trưởng nhóm","f.chat.p":"Một thanh bên kiểu Discord: mỗi dự án một biểu tượng, kim cương tím cho việc cần bạn. Nhắn cho trưởng nhóm một ý tưởng; họ biến nó thành thẻ và kế hoạch, kèm nút ✅ Bắt đầu.","f.tidy.h":"Tự giữ cho gọn gàng","f.tidy.p":"Các thẻ liên quan gộp thành một, tiêu đề rối được sửa lại, và phần kiểm tra token giữ cho mã gọn nhẹ. Ít thứ phải chuyển qua lại, ít thứ phải nghĩ hơn.","f.private.h":"Của bạn, trên máy tính của bạn","f.private.li1":"Bảng chạy ngay trên máy của bạn và chỉ trả lời bạn.","f.private.li2":"Tin nhắn riêng giữa mọi người được mã hóa đầu cuối.","f.private.li3":"Không tài khoản, không trình theo dõi, không cookie.","f.lang.h":"Bằng ngôn ngữ của bạn","f.lang.p":"Hơn 120 ngôn ngữ, từ tiếng Hà Lan, xứ Wales và Nhật đến tiếng cướp biển, Yoda và Klingon, kèm nút chuyển nhanh về tiếng Anh cho các thuật ngữ chuyên ngành.","f.service.h":"Từ một ý tưởng đến một dịch vụ thật","f.service.p":"Đã làm ra thứ gì đó với AI và giờ có người dùng? Đánh dấu nó là dịch vụ và bảng sẽ giúp bạn vận hành nó thật tốt: kiểm tra uptime, trang trạng thái công khai, sự cố có bản tổng kết, thay đổi cần một lần Go, sao lưu được kiểm tra hằng ngày. Phần Trợ giúp hướng dẫn từng bước khi bạn làm tới.","msgr.h2":"AI-gile Messenger: cả đội trong túi bạn","msgr.p1":"Trò chuyện với đội AI của bạn mà không cần mở bảng. Nhắn tin với các trưởng dự án và bạn bè, xem các bước kiểm thử của một thẻ và trả lời, tất cả ngay trên điện thoại.","msgr.p2":"Để ghép nối, hãy quét mã QR trên bảng của bạn. Lần đầu dùng? Một cuộc trò chuyện demo thân thiện sẽ dẫn bạn đi một vòng.","msgr.when":"Android trước, sau đó là bản web cho điện thoại và iPhone.","msgr.who":"Trưởng dự án của bạn","msgr.b1":"Bản sửa chế độ tối đã xong. Bạn muốn xem các bước kiểm thử không?","msgr.b2":"Có, cho mình xem nhé!","msgr.b3":"1. Mở Cài đặt. 2. Chọn Tối. Trông ổn chưa?","tl.aria":"Dòng thời gian từ cuộc trò chuyện đầu tiên đến lộ trình","tl.h2":"Từ cuộc trò chuyện đầu tiên đến điều tiếp theo","tl.lede":"Ngày giờ thật, theo múi giờ của bạn. Sau hôm nay là kế hoạch, không hứa ngày nào.","tl.today":"Hôm nay","tl.planned":"dự kiến","tl.cards.one":"{n} thẻ","tl.cards.other":"{n} thẻ","join.h2":"Cùng tham gia","join.lede":"AI-gile đang được xây bởi một con người nhỏ bé và rất nhiều agent kiên nhẫn. Hiện còn riêng tư, trong bản alpha kín với bạn bè. Muốn thử khi nó mở ra không?","join.btn":"Đăng ký quan tâm","join.small":"Chúng tôi sẽ gửi email cho bạn, không gì khác","footer.tag":"AI-gile. Không trình theo dõi, không cookie, không cà phê họp đứng.","footer.licence":"Giấy phép doanh nghiệp","footer.status":"Trạng thái","footer.privacy":"Chúng tôi giữ những gì","footer.thanks":"Cuộc gọi nhờ có ChilledChat","form.sending":"Đang gửi…","form.failed":"Không được rồi: hãy thử lại sau.","form.offline":"Không kết nối được với AI-gile: hãy thử lại sau.","form.keep":"Chúng tôi chỉ dùng thông tin này để trả lời bạn, rồi xóa đi. Không trình theo dõi, không cookie.","form.keepLink":"Chúng tôi giữ những gì","interest.title":"AI-gile: báo cho tôi khi alpha mở","interest.description":"Để lại email để biết khi nào bản alpha hoặc beta kín của AI-gile mở ra.","interest.h1":"🔔 Báo cho tôi khi mở","interest.lede":"AI-gile đang ở giai đoạn tiền alpha kín. Để lại email, chúng tôi sẽ viết đúng một lần, khi có chỗ cho bạn.","interest.email":"Email của bạn","interest.which":"Bản thử nào?","interest.alpha":"Alpha kín: sớm, còn thô, thay đổi nhiều","interest.beta":"Beta: ổn định hơn, muộn hơn","interest.both":"Bản nào đến trước cũng được","interest.submit":"Ghi tên tôi vào danh sách","interest.thanks":"Cảm ơn bạn! Bạn đã có tên trong danh sách.","licence.title":"AI-gile: giấy phép doanh nghiệp","licence.description":"Dùng AI-gile cho công việc kinh doanh? Hãy đăng ký giấy phép doanh nghiệp miễn phí.","licence.h1":"📜 Giấy phép doanh nghiệp","licence.lede":"Dùng AI-gile ở chỗ làm? Hãy cho chúng tôi biết bạn là ai và làm gì. Nếu việc đó mang lại chút điều tốt, giấy phép là miễn phí.","licence.company":"Công ty","licence.website":"Trang web","licence.what":"Bạn làm gì","licence.how":"Nó giúp ích cho thế giới thế nào","licence.email":"Email","licence.submit":"Đăng ký","licence.thanks":"Cảm ơn bạn! Chúng tôi sẽ trả lời qua email.","status.title":"Trạng thái AI-gile","status.h1":"Trạng thái AI-gile","status.quiet":"Mọi thứ yên ắng","status.intro":"AI-gile có đang hoạt động không? Trang này kiểm tra trang web, chia sẻ bảng, cuộc gọi và bản tải xuống mỗi 5 phút.","status.up":"Đang hoạt động (phản hồi trong {ms} ms)","status.slow":"Không phản hồi lần kiểm tra gần nhất, đang thử lại","status.down":"Ngừng hoạt động: không phản hồi hai lần kiểm tra gần nhất","status.svc.web":"Trang web","status.svc.web.offers":"Trang này: AI-gile là gì, và biểu mẫu “Báo cho tôi khi mở”","status.svc.boards":"Chia sẻ bảng","status.svc.boards.offers":"Bảng công khai, tin nhắn giữa bạn bè và lời mời","status.svc.calls":"Cuộc gọi","status.svc.calls.offers":"Thoại, video và chia sẻ màn hình trong AI-gile","status.svc.download":"Tải xuống","status.svc.download.offers":"Bộ cài đặt Windows và liên kết mời","status.checking":"Đang kiểm tra…","status.offline":"Hiện chưa kết nối được dịch vụ trạng thái (đang thử lại)","status.updated":"cập nhật {ago}","status.justNow":"vừa xong","status.min":"{n} phút trước","status.hours":"{n} giờ trước","status.days":"{n} ngày trước","privacy.title":"AI-gile: chúng tôi giữ những gì","privacy.h1":"Chúng tôi giữ những gì","privacy.lede":"Nói ngắn gọn: chỉ những gì bạn gửi cho chúng tôi, và không giữ lâu.","privacy.only":"Chỉ những gì bạn gửi cho chúng tôi: những gì bạn nhập vào biểu mẫu, như email của bạn. Ngoài ra không có gì khác về bạn.","privacy.sealed":"Dữ liệu được niêm phong để máy chủ của chúng tôi không đọc được: ngay trong trình duyệt của bạn trước khi gửi đi (với trình duyệt cũ hơn thì ngay khi đến nơi). Chỉ bảng của chính chúng tôi mới mở được.","privacy.server":"Dữ liệu bị xóa khỏi máy chủ ngay khi đến bảng của chúng tôi. Thứ gì còn sót lại sau 30 ngày cũng sẽ bị xóa.","privacy.board":"Chúng tôi chỉ giữ nó trên bảng cho đến khi đã trả lời bạn, rồi xóa luôn ở đó.","privacy.none":"Không trình theo dõi, không cookie, không phân tích.","privacy.local":"Ngôn ngữ và lựa chọn giao diện sáng hay tối của bạn chỉ nằm trong trình duyệt của bạn. Chúng không bao giờ được gửi cho chúng tôi.","privacy.ask":"Muốn xóa sớm hơn? Hãy trả lời email của chúng tôi và nói vậy.","live.h2":"Xem nó được xây dựng, trực tiếp","live.caption":"Mọi thẻ đều được ẩn: bạn thấy hình dạng của công việc, không phải câu chữ.","live.watching.one":"trực tiếp: {n} người đang xem","live.watching.other":"trực tiếp: {n} người đang xem","live.last.now":"Thẻ cuối cùng vừa được chuyển xong","live.last.min.one":"Thẻ cuối cùng được chuyển {n} phút trước","live.last.min.other":"Thẻ cuối cùng được chuyển {n} phút trước","live.last.hour.one":"Thẻ cuối cùng được chuyển {n} giờ trước","live.last.hour.other":"Thẻ cuối cùng được chuyển {n} giờ trước","live.last.day.one":"Thẻ cuối cùng được chuyển {n} ngày trước","live.last.day.other":"Thẻ cuối cùng được chuyển {n} ngày trước","live.offline":"Bảng trực tiếp đang nghỉ một chút. Hãy quay lại sớm nhé.","live.cols":"Backlog|Cần làm|Đang làm|Nhóm kiểm tra|Bạn cần test|Cho nhóm|Xong"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robot.","Agent."]},{"n":2,"texts":["Kanban robot.","Giao agent.","Việc xong."]},{"n":3,"texts":["Kanban cho robot.","Ý thành tính năng.","Kanban agent miễn phí."]},{"n":5,"texts":["Bảng kanban do agent vận hành.","Bạn viết thẻ. Agent làm.","Miễn phí, tại máy, hơi ngộ."]},{"n":8,"texts":["Bảng kanban miễn phí, nơi các agent AI làm việc.","Viết ý tưởng. Agent làm ra. Bạn chấp nhận.","Agile cho một con người và nhiều robot kiên nhẫn."]},{"n":13,"texts":["Một bảng kanban trên máy bạn, nơi các agent AI nhận thẻ về làm.","Viết một ý tưởng. Một nhóm agent làm ra. Người kiểm thử xem lại.","Miễn phí, không tài khoản, không theo dõi: một bảng, vài robot, và bạn làm chủ."]},{"n":21,"texts":["AI-gile là bảng kanban để làm việc cùng các agent lập trình AI. Họ nhận thẻ về làm; bạn thử và chấp nhận chúng.","Mỗi dự án có một trưởng nhóm và các agent AI. Bình luận vào thẻ bất kỳ, cả nhóm bắt tay vào việc.","Một bảng việc cần làm cá nhân, miễn phí, chạy ngay trên máy bạn. Người làm là robot. Người gật đầu là bạn."]},{"n":34,"texts":["Bạn đặt ý tưởng lên bảng. Một nhóm agent AI biến chúng thành tính năng chạy được, kiểm thử, rồi giao lại kèm các bước để thử. Chưa gì được tính là xong cho đến khi bạn nói vậy.","AI-gile là bảng kanban tự chế mà Rich làm với rất nhiều sự giúp đỡ của chính các agent mà nó đang quản lý. Miễn phí, chạy trên máy bạn, và chia sẻ cho bạn bè chứ không bán.","Hình dung một bảng kanban bình thường, với các cột từ Backlog đến Xong, chỉ khác là thẻ do các agent AI nhận làm. Họ báo cáo tiến độ, hỏi khi bị kẹt, và luôn chờ bạn giơ ngón tay cái."]},{"n":55,"texts":["AI-gile là một bảng kanban mà cả nhóm đều là agent AI. Mỗi dự án có một trưởng nhóm lên kế hoạch công việc và những người trợ giúp làm ra nó. Khi một tính năng sẵn sàng, một người kiểm thử AI thử nó và chụp màn hình, rồi nó rơi vào chồng của bạn. Chấp nhận, hoặc bình luận để họ làm lại.","Nó bắt đầu từ cách một người theo dõi cùng lúc thật nhiều phiên lập trình AI, rồi lớn thành một chiếc bảng đúng nghĩa. Nó chạy trên máy bạn, không cần tài khoản, không có trình theo dõi. Miễn phí cho bạn bè và những ai tò mò. Nó cũng chưa xong, nên hãy chờ vài chỗ gồ ghề và đôi bất ngờ.","Đây là phiên bản thành thật. Bạn vẫn phải có ý tưởng, và vẫn phải kiểm tra kết quả. Việc AI-gile làm là mọi thứ ở giữa: giữ các thẻ có thứ tự, đánh thức đúng agent khi bạn bình luận, cho thấy chính xác điều gì đã đổi, và gom tất cả vào một chồng ngắn dành cho bạn."]},{"n":89,"texts":["AI-gile là một bảng kanban miễn phí chạy ngay trên máy tính của bạn. Thay vì con người, mỗi dự án có một nhóm agent AI: một trưởng nhóm biến ý tưởng của bạn thành thẻ và kế hoạch, cùng những người trợ giúp nhận thẻ theo thứ tự ưu tiên. Khi có thứ gì đó làm xong, một người kiểm thử AI làm theo các bước thử và cho bạn xem điều đã thấy. Rồi nó chờ trong một chồng mang tên Cho bạn. Bạn chấp nhận, hoặc bình luận và cả nhóm thử lại. Không có gì đến được cột Xong nếu thiếu bạn.","Có vài tính năng bạn có thể không ngờ tới. Một người gác đêm giữ cột Cần làm luôn đầy khi bạn ngủ, chọn những thẻ không cần bạn trả lời. Bộ đếm token cho thấy các agent đã dùng bao nhiêu hôm nay và tuần này, còn Chế độ Không Token bảo họ ngừng tiêu. Bạn có thể nhắn tin cho bạn bè, và tin nhắn riêng được mã hóa đầu cuối. Bảng nói khoảng 120 ngôn ngữ, gồm tiếng Hà Lan, Flemish, cướp biển và Klingon. Không thứ nào tốn một xu, và cũng chẳng ai đang cố bán gì cho bạn.","AI-gile là một dự án nhỏ, cá nhân, không phải một công ty. Rich muốn trông nom vài dự án lập trình AI mà không phải mở từng ứng dụng ra xem, nên anh và các agent làm một chiếc bảng cho việc đó, rồi dùng chính chiếc bảng ấy để làm nốt phần còn lại. Nó đang ở giai đoạn tiền alpha kín, nghĩa là phần lớn chạy được, cho một nhúm bạn bè. Không có trang bảng giá, không bản tin, không kế hoạch tăng trưởng. Nếu nghe hữu ích, bạn có thể xin thử khi nó mở rộng hơn một chút."]},{"n":144,"texts":["AI-gile là một bảng kanban cho một con người và rất nhiều agent AI. Nó chạy trên máy tính của bạn và hoàn toàn miễn phí. Bạn thêm các dự án, và mỗi dự án có một trưởng nhóm cùng một nhóm nhỏ. Bạn trò chuyện với trưởng nhóm, hơi giống Discord, và mô tả một ý tưởng; trưởng nhóm biến nó thành thẻ và kế hoạch, rồi chờ bạn bấm Bắt đầu. Cả nhóm làm lần lượt các thẻ theo thứ tự ưu tiên, bằng một dòng lệnh đơn giản làm riêng cho các mô hình ngôn ngữ. Trước khi bất cứ thứ gì quay lại với bạn, một người kiểm thử AI làm theo các bước trong một bản sao của ứng dụng và đính kèm ảnh chụp màn hình. Việc xong rơi vào chồng của bạn cùng các tệp đã đổi và phần khác biệt. Bạn chấp nhận, hoặc để lại bình luận và cả nhóm thức dậy làm lại. Chỉ bạn mới chuyển được thẻ sang Xong.","Một ngày với AI-gile, đại khái thế này. Buổi tối bạn để lại vài bình luận: nút này sai chỗ, danh sách kia nên được sắp xếp, có thể thêm chế độ tối không. Bạn đi ngủ. Các agent đọc bình luận, sửa, kiểm thử rồi giao lại cho bạn. Nếu cột Cần làm cạn, người gác đêm sẽ lấy từ backlog những thẻ không cần bạn trả lời để lấp đầy. Sáng ra chỉ có một chồng ngắn: vài câu hỏi và vài thứ để thử, mỗi cái kèm các bước mà người còn ngái ngủ cũng làm theo được và một ảnh chụp màn hình cho thấy nó chạy. Bạn bấm qua, chấp nhận cái tốt và gửi trả phần còn lại. Bộ đếm token cho thấy tất cả tốn bao nhiêu, và Chế độ Không Token dành cho những tuần phải tiết kiệm. Rồi bạn ăn sáng, việc mà các agent chưa giúp được.","Trước hết, AI-gile không phải là gì. Nó không phải công ty khởi nghiệp, không bán, và không ai thu thập dữ liệu của bạn. Nó là một bảng miễn phí chạy trên máy bạn, không tài khoản, không trình theo dõi, không cookie. Còn nó là gì: một nơi gọn gàng để thấy mọi dự án lập trình AI cùng lúc, với một nhóm agent làm thẻ và bạn là người quyết định. Nó gộp các thẻ liên quan, sửa tiêu đề rối, và để mắt xem mã còn gọn đến đâu. Nó nói khoảng 120 ngôn ngữ, từ tiếng Hà Lan và Flemish đến cướp biển và Klingon. Bạn bè có thể nhắn nhau, riêng tư và được mã hóa. Nó do Rich và rất nhiều agent kiên nhẫn làm ra, phần lớn bằng cách tự dùng chính nó. Nó đang ở giai đoạn tiền alpha kín, nên có chỗ còn thô. Nếu nghe vui, hãy hỏi lịch sự, biết đâu bạn vào sớm."]}],"quips":{"1":"Một từ. Táo bạo. Có lẽ hơi quá táo bạo.","3":"Ba từ. Đã thật thà hơn đa số trang sản phẩm.","8":"Tám từ. Vẫn ngắn hơn một buổi họp đứng.","21":"Nhân tiện, các độ dài là story point. Dĩ nhiên rồi.","55":"Năm mươi lăm từ. Trong lúc bạn đọc, hai thẻ đã xong.","144":"Đó là bản dài nhất. Không có 233. Các agent đi ngủ rồi."}},"timeline":{"first-idea.name":"Ý tưởng đầu tiên","first-idea.line":"Cuộc trò chuyện đầu tiên, khi chưa có dòng mã nào.","first-board.name":"Bảng đầu tiên","first-board.line":"Một bảng theo dõi chính quá trình xây nó: thẻ, cột, kéo thả, dự án.","team-roles.name":"Nhóm và vai trò","team-roles.line":"Hồ sơ agent, mẫu nhóm, không gian và ai làm gì.","install.name":"Cài đặt và phát hành","install.line":"Một tệp zip bạn bè cài được, tự cập nhật, các kênh và quay lui.","usage-saver.name":"Tiết kiệm lượt dùng","usage-saver.line":"Đo chi phí mỗi lần chạy, giữ mã gọn nhẹ, giữ hạn mức của bạn.","friends.name":"Bạn bè và chia sẻ","friends.line":"Tin nhắn riêng, máy chuyển tiếp đã xáo trộn, lời mời, vai trò và dự án chung.","languages.name":"Ngôn ngữ","languages.line":"Mọi chữ trên màn hình nằm trong một tệp ngôn ngữ, tiếng Hà Lan và tiếng Flemish trước.","ai-tester.name":"Người kiểm thử AI","ai-tester.line":"Một người kiểm thử xem mọi lần bàn giao trước và cho xem điều đã thấy.","website.name":"Trang web","website.line":"aigile.lol, trang giới thiệu và dòng thời gian này.","streaming.name":"Trò chuyện và phát trực tiếp","streaming.line":"Discord, Twitch, OBS, chế độ streamer, GIF và emoji.","no-ai.name":"Bản không AI","no-ai.line":"Một bảng cho người lập trình không dùng AI, và các bảng công khai.","night-watch.name":"Gác đêm","night-watch.line":"Một người gác và Scrum Master giữ các nhóm đúng việc khi bạn ngủ.","p-more.name":"Mọi thứ còn lại","p-more.line":"Những ý tưởng nhỏ hơn vẫn đang chờ đến lượt.","p-android.name":"Điện thoại và Android","p-android.line":"Vào bảng của bạn từ điện thoại, rồi một ứng dụng Android riêng.","p-release.name":"Alpha và xa hơn","p-release.line":"Alpha kín, trang web chính thức, rồi beta.","p-languages.name":"Thêm ngôn ngữ","p-languages.line":"Hơn một trăm ngôn ngữ, và chế độ đắm mình cho người học.","p-engines.name":"Thêm công cụ AI","p-engines.line":"Chọn Claude, Codex hoặc Gemini cho từng agent.","p-pro.name":"Thực hành chuyên nghiệp","p-pro.line":"Nhãn rủi ro, cổng hợp nhất, thẻ sự cố và rào chắn an toàn.","p-self.name":"Chăm sóc bạn","p-self.line":"Chế độ mệt mỏi, nhắc nhở chăm sóc bản thân và 4:20.","p-servers.name":"Máy chủ và quy mô","p-servers.line":"Cài đặt máy chủ toàn cục, vai trò và kế hoạch để phát triển.","p-livestream.name":"Tiện ích phát trực tiếp","p-livestream.line":"Trò chuyện Twitch, emoji tùy chỉnh và chế độ xem trực tiếp công khai."},"words":{"button":"📖 Thuật ngữ chuyên ngành","h":"📖 Giải thích từ ngữ","intro":"Những từ bạn gặp trong AI-gile, nói bằng lời dễ hiểu: làm ra sản phẩm, thay đổi nó an toàn, giữ cho nó chạy ổn với người dùng, và làm việc như một nhóm cùng AI.","search":"Tìm một từ…","none":"Không có từ nào khớp.","close":"Đóng","count":{"one":"{count} từ","other":"{count} từ"},"groups":[{"id":"build","name":"🛠️ Làm ra sản phẩm"},{"id":"change","name":"🔀 Thay đổi an toàn"},{"id":"run","name":"🛎️ Vận hành dịch vụ"},{"id":"team","name":"🤝 Làm việc theo nhóm (và với AI)"}],"list":[{"id":"repo","g":"build","word":"Repo","text":"Thư mục code của dự án cùng toàn bộ lịch sử commit, thường cũng được giữ trên GitHub.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"Một nhánh làm việc riêng trong code, để có thể thay đổi mà không đụng đến bản chính.","also":["branches"]},{"id":"commit","g":"build","word":"Commit","text":"Một bản chụp đã lưu của code, kèm ghi chú ngắn về điều đã đổi. Bạn luôn có thể quay lại một bản.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"Đẩy các bản chụp đã lưu (commit) từ máy này lên GitHub, để chúng được sao lưu và chia sẻ."},{"id":"merge","g":"build","word":"Merge","text":"Nhập các thay đổi của một branch trở lại bản chính."},{"id":"pr","g":"build","word":"Pull request","text":"Yêu cầu kiểm tra các thay đổi của một branch rồi merge vào bản chính.","also":["PR"]},{"id":"refactor","g":"build","word":"Refactor","text":"Dọn dẹp code mà không đổi việc nó làm: tệp nhỏ hơn, tên rõ hơn, bớt lặp lại."},{"id":"bug","g":"build","word":"Bug","text":"Chỗ nào đó không hoạt động đúng như lẽ ra phải thế.","also":["bugs","lỗi"]},{"id":"test","g":"build","word":"Test","text":"Thử một phần việc đã xong để kiểm tra nó làm đúng điều được yêu cầu, trước khi bạn chấp nhận.","also":["tests","kiểm thử"],"noTip":1},{"id":"qa","g":"build","word":"QA","text":"Viết tắt của quality assurance, tức là đảm bảo chất lượng: các bước kiểm tra tự động chạy trước khi bất cứ thứ gì được đưa vào hoạt động. Khi QA báo đỏ là có gì đó không đạt, và phải sửa xong mới đưa vào hoạt động được.","also":["kiểm tra chất lượng","đảm bảo chất lượng","quality assurance","quality checks"]},{"id":"deploy","g":"change","word":"Deploy","text":"Đưa một phiên bản mới lên chạy thật, ví dụ lên máy chủ nơi mọi người dùng."},{"id":"release","g":"change","word":"Bản phát hành","text":"Một gói công việc đã xong, có tên, được đưa vào hoạt động cùng lúc, kèm ghi chú ngắn về những gì đã thay đổi. 🚀 Bản phát hành tự viết ghi chú từ các thẻ đã xong.","also":["phát hành","release","releases"]},{"id":"rollback","g":"change","word":"Rollback","text":"Quay lại phiên bản gần nhất còn chạy tốt khi bản mới gây rắc rối. Trong AI-gile, nó tạo một danh sách kiểm tra từ các bước hoàn tác được ghi trên mỗi thay đổi.","also":["quay lại bản cũ","hoàn tác","roll back","roll-back","rolled back"]},{"id":"live","g":"change","word":"Live","text":"Phiên bản thật mà mọi người đang dùng, khác với bản sao để thử nghiệm. Đưa thứ gì lên đó gọi là đưa vào hoạt động. Lập trình viên còn gọi nó là production.","also":["production","bản chạy thật","môi trường thật"],"noTip":1},{"id":"change","g":"change","word":"Thay đổi","text":"Một thay đổi có kế hoạch cho thứ mà mọi người đang dựa vào, được ghi ra trước: làm gì, vì sao, rủi ro, khi nào và cách hoàn tác. Bắt đầu bằng 🔀 Đề xuất thay đổi.","also":["yêu cầu thay đổi","change","change request","change requests"],"noTip":1},{"id":"risk","g":"change","word":"Rủi ro","text":"Điều có thể xảy ra sai, được chấm điểm theo khả năng xảy ra và mức độ tệ. ⚠️ Rủi ro gom chúng vào một danh sách, điểm cao nhất lên đầu, mỗi cái có một ngày để xem lại.","also":["các rủi ro","sổ rủi ro","risk","risks","risk register"]},{"id":"chgwin","g":"change","word":"Khung giờ thay đổi","text":"Những khoảng thời gian được phép đưa thay đổi vào hoạt động, ví dụ một tối thứ Ba yên ắng. Ngoài khung giờ, thẻ thay đổi không thể hoàn tất, trừ khi là trường hợp khẩn cấp.","also":["change window","change windows"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"Một lần biểu quyết nhanh ngay trước khi thay đổi được đưa vào hoạt động: mỗi người cần duyệt sẽ nói Go hoặc No go. Chỉ khi mọi người đồng ý thì mới làm tiếp.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Phê duyệt","text":"Chờ một cái gật đầu trước khi bắt đầu làm. Thẻ do bạn bè tạo, hoặc một thay đổi, sẽ chờ trong ✅ Phê duyệt cho đến khi bạn duyệt hoặc từ chối.","also":["duyệt","approval","approvals"]},{"id":"quiettime","g":"change","word":"Giờ yên tĩnh","text":"Một khoảng thời gian, như lúc stream, demo hay ban đêm, khi không đưa gì vào hoạt động. Các nhóm vẫn làm và test bình thường, nhưng việc đưa vào hoạt động phải chờ đến khi hết giờ. Ở nơi khác người ta gọi là change freeze.","also":["đóng băng thay đổi","quiet time","quiet times","change freeze"]},{"id":"service","g":"run","word":"Dịch vụ","text":"Thứ bạn làm ra mà mọi người dựa vào, như một trang web hay một ứng dụng, được chăm sóc để luôn chạy tốt. Đánh dấu “Dự án này là một dịch vụ” rồi ghi nó cung cấp gì, ai dùng và ai trực.","also":["các dịch vụ","service","services"]},{"id":"uptime","g":"run","word":"Kiểm tra uptime","text":"Một lần kiểm tra tự động, vài phút một lần, xem dịch vụ của bạn còn phản hồi không. Nếu nó thất bại vài lần liên tiếp, AI-gile tự mở một thẻ sự cố.","also":["uptime","uptime check","uptime checks","thời gian hoạt động"]},{"id":"statuspage","g":"run","word":"Trang trạng thái","text":"Một trang công khai cho biết dịch vụ có đang chạy không (xanh, cam hay đỏ) kèm cập nhật mới nhất, để người dùng tự xem thay vì phải hỏi.","also":["status page","status pages"]},{"id":"incident","g":"run","word":"Sự cố","text":"Thứ đang hỏng với người dùng ngay lúc này, như trang web bị sập. Thẻ 🔥 sự cố được chen lên đầu hàng: làm cho nó chạy lại là việc đầu tiên.","also":["các sự cố","incident","incidents"]},{"id":"major","g":"run","word":"Sự cố lớn","text":"Một sự cố lớn: nhiều người bị ảnh hưởng, hoặc tiền bạc hay dữ liệu gặp nguy. Một nút bấm đưa mọi nhóm vào cuộc (swarm), đánh thức người đang trực và yêu cầu cập nhật trạng thái mỗi 30 phút.","also":["sự cố nghiêm trọng","major incident","major incidents"]},{"id":"oncall","g":"run","word":"Trực","text":"Là người trả lời khi có gì đó hỏng, kể cả ban đêm. Mỗi dịch vụ có một thành viên trực, người được đánh thức đầu tiên khi dịch vụ đó có sự cố.","also":["trực sự cố","người trực","on call","on-call"]},{"id":"replyby","g":"run","word":"Hạn trả lời","text":"Một thẻ được chờ câu trả lời đầu tiên bao lâu, ví dụ một giờ cho sự cố. Quá hạn thì thẻ hiện đồng hồ đỏ, để không có gì bị lặng lẽ bỏ quên. Còn gọi là response target.","also":["thời hạn trả lời","reply-by time","response target","response targets"]},{"id":"postmortem","g":"run","word":"Tổng kết sự cố","text":"Một lần nhìn lại ngắn sau sự cố: chuyện gì đã xảy ra, điều gì đã giúp và cần thay đổi gì, không đổ lỗi cho ai. Không có nó thì không đóng được sự cố. Còn gọi là post-mortem.","also":["post-mortem","post-mortems","postmortem","post-incident review"]},{"id":"problem","g":"run","word":"Vấn đề","text":"Nguyên nhân ẩn đằng sau một hay nhiều sự cố. Thẻ 🧩 vấn đề gom những sự cố cứ lặp lại, để tìm ra nguyên nhân và sửa dứt điểm.","also":["các vấn đề","problem","problems"],"noTip":1},{"id":"rootcause","g":"run","word":"Nguyên nhân gốc","text":"Lý do thật khiến thứ gì đó hỏng, không chỉ là cái bạn thấy bị lỗi. Sửa nguyên nhân gốc thì sự cố không quay lại nữa.","also":["nguyên nhân gốc rễ","root cause","root causes"]},{"id":"workaround","g":"run","word":"Cách xử lý tạm","text":"Một cách giữ mọi thứ chạy cho đến khi có bản sửa thật, như khởi động lại thứ gì đó khi nó bị treo. Nó được ghi trên thẻ vấn đề để không ai phải tự mò lại.","also":["giải pháp tạm","workaround","workarounds"]},{"id":"knownerror","g":"run","word":"Lỗi đã biết","text":"Một vấn đề đã hiểu rõ nguyên nhân và đã có cách xử lý tạm, nhưng chưa được sửa. 🧩 Lỗi đã biết liệt kê chúng, để mọi người dùng cách xử lý tạm thay vì đào bới lại.","also":["các lỗi đã biết","known error","known errors"]},{"id":"runbook","g":"run","word":"Runbook","text":"Hướng dẫn từng bước để sửa một kiểu rắc rối đã biết, để lần nào cũng làm giống nhau và nhanh. Sau một sự cố lớn, nhóm có thể đề xuất một runbook để bạn duyệt.","also":["runbooks","sổ tay xử lý"]},{"id":"backup","g":"run","word":"Sao lưu","text":"Một bản sao dữ liệu của bạn được lưu từ trước, để dựa vào nếu có gì bị mất hay hỏng. AI-gile sao lưu các bảng của bạn mỗi ngày.","also":["bản sao lưu","backup","backups","back-up","back-ups"]},{"id":"restore","g":"run","word":"Khôi phục","text":"Lấy dữ liệu lại từ bản sao lưu. Một bản sao lưu chỉ thật sự có giá trị khi bạn biết nó khôi phục được, nên thỉnh thoảng hãy thử.","also":["đã khôi phục","restore","restored"]},{"id":"backlog","g":"team","word":"Backlog","text":"Ý tưởng và công việc chưa được lên kế hoạch. Không có gì ở đó được làm cho đến khi chuyển sang Cần làm."},{"id":"sprint","g":"team","word":"Sprint","text":"Một quãng làm việc ngắn (thường một hoặc hai tuần) với một bộ thẻ đã thống nhất để hoàn thành.","also":["sprints"]},{"id":"standup","g":"team","word":"Stand-up","text":"Một buổi cập nhật nhanh: mỗi thành viên đã làm gì, sẽ làm gì tiếp và điều gì đang cản trở.","also":["standup","stand-ups"]},{"id":"kanban","g":"team","word":"Kanban","text":"Một bảng có các cột (Cần làm, Đang làm, Xong) nơi thẻ di chuyển từ trái sang phải khi công việc tiến triển."},{"id":"wip","g":"team","word":"Giới hạn WIP","text":"Work in progress (việc đang làm): số thẻ tối đa một cột nên chứa, để nhóm làm xong việc trước khi bắt đầu thêm.","also":["WIP"]},{"id":"dod","g":"team","word":"Definition of Done","text":"Danh sách ngắn của nhóm về thế nào là “xong”, như đã test và đã giải thích, trước khi thẻ được giao cho bạn. Người anh em sinh đôi của nó, Definition of Ready, cho biết khi nào một thẻ đủ rõ để bắt đầu.","also":["Definition of Ready","DoD","DoR","định nghĩa hoàn thành"]},{"id":"testpile","g":"team","word":"Chồng thử","text":"Các thẻ đã xong đang chờ bạn thử, lần lượt từng cái. Chấp nhận một thẻ hoặc gửi trả kèm ghi chú, và thẻ tiếp theo hiện lên.","also":["test pile","test piles"]},{"id":"retro","g":"team","word":"Retro","text":"Một lần nhìn lại cách nhóm làm việc, để thống nhất một điều cần làm tốt hơn. Trong AI-gile, retro đề xuất một thay đổi trong cách làm việc của nhóm, và bạn nói Go hoặc Chưa đâu.","also":["retros","retrospective","retrospectives","họp nhìn lại"]},{"id":"peerreview","g":"team","word":"Đánh giá ngang hàng","text":"Thêm một đôi mắt: một AI khác kiểm tra công việc của từng thẻ trước khi đến tay bạn, nên ít lỗi lọt qua hơn.","also":["review code","peer review","code review"]},{"id":"swarm","g":"team","word":"Swarm","text":"Tất cả cùng xắn tay: mọi nhóm gác việc khác để giúp một dự án gấp cho đến khi xong. Trong lúc đó các dự án khác phải chờ.","also":["swarming","dồn lực"]},{"id":"scrummaster","g":"team","word":"Scrum Master","text":"Người giữ cho công việc trôi chảy: phát hiện thẻ bị kẹt, nhắc các nhóm và nhắc bạn những gì đang chờ. Trong AI-gile, Lead Scrum Master làm việc này cho mọi dự án.","also":["Lead Scrum Master"]},{"id":"agent","g":"team","word":"Agent","text":"Một AI tự làm việc trên một nhiệm vụ: đọc code, thay đổi, chạy kiểm tra và báo cáo lại.","also":["agents"]},{"id":"token","g":"team","word":"Token","text":"Đơn vị tính mức dùng AI: xấp xỉ vài chữ cái văn bản được đọc hoặc viết. Càng ít token, gói của bạn càng còn nhiều.","also":["tokens"]},{"id":"hook","g":"team","word":"Hook","text":"Một lệnh nhỏ tự chạy vào một thời điểm định sẵn, vd. khi một phiên AI bắt đầu, để nhóm nghe được bình luận của bạn.","also":["hooks"]}]}};
